// The score readouts' lettering, shared by the cabinets' HUDs (#212): Sweet
// Sam's thick labels, and the words Brass Monkey adds in the same letters.
// hud.png is `hudSheetRows`, generated by scripts/gen-ui-art.ts.

/**
 * "1UP" and "HIGH SCORE" in the Go game's thick lettering (imported from its
 * maze image). Sweet Sam's maze.png bakes them into its top row at x
 * `scoreLabelsX`, as the Go maze had them.
 */
export const scoreLabelsArt: readonly string[] = [
  "..ww...ww...ww.wwwwww..........................ww...ww..wwwwww...wwwww.ww...ww..........wwww.....wwww...wwwww..wwwwww...wwwwww",
  ".www...ww...ww.ww...ww.........................ww...ww....ww....ww.....ww...ww.........ww..ww...ww..ww.ww...ww.ww...ww..ww....",
  "..ww...ww...ww.ww...ww.........................ww...ww....ww...ww......ww...ww.........ww......ww......ww...ww.ww...ww..ww....",
  "..ww...ww...ww.ww...ww.........................wwwwwww....ww...ww..www.wwwwwww..........wwwww..ww......ww...ww.ww..www..wwwww.",
  "..ww...ww...ww.wwwwww..........................ww...ww....ww...ww...ww.ww...ww..............ww.ww......ww...ww.wwwww....ww....",
  "..ww...ww...ww.ww..............................ww...ww....ww....ww..ww.ww...ww.........ww...ww..ww..ww.ww...ww.ww.www...ww....",
  "wwwwww..wwwww..ww..............................ww...ww..wwwwww...wwwww.ww...ww..........wwwww....wwww...wwwww..ww..www..wwwwww",
];
export const scoreLabelsX = 26;
/** Where the score and high-score dials sit, under the labels. */
export const scoreDialsAt = { score: { x: 8, y: 8 }, high: { x: 8 * 11, y: 8 } };

function labelLetter(x: number): readonly string[] {
  return scoreLabelsArt.map((row) => row.slice(x, x + 7));
}

/** The thick letters the words need: those the labels have, cut from them, and B, N and L drawn to match. */
const hudLetters = {
  U: labelLetter(7),
  P: labelLetter(15),
  S: labelLetter(87),
  O: labelLetter(103),
  B: ["wwwwww.", "ww...ww", "ww...ww", "wwwwww.", "ww...ww", "ww...ww", "wwwwww."],
  N: ["ww...ww", "www..ww", "wwww.ww", "ww.wwww", "ww..www", "ww...ww", "ww...ww"],
  L: ["ww.....", "ww.....", "ww.....", "ww.....", "ww.....", "ww.....", "wwwwww."],
} as const;

type HudLetter = keyof typeof hudLetters;

/** A word in the thick letters, one letter per 8 px tile as in "SCORE". */
function word(letters: readonly HudLetter[]): readonly string[] {
  return scoreLabelsArt.map((_, y) => letters.map((ch) => `${hudLetters[ch][y] ?? ""}.`).join(""));
}

export const bonusLabelArt: readonly string[] = word(["B", "O", "N", "U", "S"]);
export const loopLabelArt: readonly string[] = word(["L", "O", "O", "P"]);

/** hud.png: the score labels, BONUS and LOOP, each in a band `hudBandHeight` tall. */
export const hudBandHeight = 8;
export const hudSheetWidth = 126;
export const hudSheetRows: readonly string[] = [scoreLabelsArt, bonusLabelArt, loopLabelArt].flatMap((rows) =>
  rows.map((r) => r.padEnd(hudSheetWidth, ".")).concat(".".repeat(hudSheetWidth)),
);
export const hudLabels = { scores: 0, bonus: 1, loop: 2 } as const;
/** Each label's width in hud.png, and its band's glyph height. */
export const hudLabelWidths = { scores: hudSheetWidth, bonus: 40, loop: 32 } as const;
export const hudLabelHeight = 7;
